from math import gcd
class Solution:
    def maxStrength(self, nums):
        best = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                g = gcd(nums[i], nums[j])
                best = max(best, nums[i] // g * nums[j] // g)
        return best

