class Solution {
public:
    int maxStrength(vector<int>& nums) {
        long long best = 0;
        int n = nums.size();
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                long long g = std::gcd(nums[i], nums[j]);
                best = max(best, (long long)nums[i] / g * (nums[j] / g));
            }
        return (int)best;
    }
};

c.java:
class Solution {
    public int maxStrength(int[] nums) {
        long best = 0;
        for (int i = 0; i < nums.length; i++)
            for (int j = i + 1; j < nums.length; j++) {
                long g = gcd(nums[i], nums[j]);
                best = Math.max(best, (long) nums[i] / g * (nums[j] / g));
            }
        return (int) best;
    }
    private long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
}

