var maxStrength = function(nums) {
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    let best = 0;
    for (let i = 0; i < nums.length; i++)
        for (let j = i + 1; j < nums.length; j++) {
            const g = gcd(nums[i], nums[j]);
            best = Math.max(best, (nums[i] / g) * (nums[j] / g));
        }
    return best;
};
